import{_ as t,o as a,c as o,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"1976年 · 保险复苏与业绩新高","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1976年.md","filePath":"05_quotes/by-year/1976年.md"}'),r={name:"05_quotes/by-year/1976年.md"};function s(c,e,h,u,_,i){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_1976年-·-保险复苏与业绩新高" tabindex="-1">1976年 · 保险复苏与业绩新高 <a class="header-anchor" href="#_1976年-·-保险复苏与业绩新高" aria-label="Permalink to &quot;1976年 · 保险复苏与业绩新高&quot;">​</a></h1><blockquote><p>经历了业绩惨淡的两年后，1976年公司的经营业绩实现了显著改善。营业利润达到1607.3万美元，创下历史新高。——巴菲特（46岁）</p></blockquote><p>本页收录1976年致股东信中的经典语录。1976年是从谷底强势反弹的一年：营业利润1607万美元创历史新高，ROE从7.6%反弹至17.3%。保险承保利润率大幅改善，综合赔付率从115.4%降至98.7%。菲尔·利舍领导的国民赔偿保险是这次反弹的核心引擎。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>经历了业绩惨淡的两年后，1976年公司的经营业绩实现了显著改善。</p></blockquote><blockquote><p>从金额来看，1976年公司营业利润达到1607.3万美元，折合每股收益16.47美元。尽管这一数字创下了历史新高，但我们始终认为，股东权益回报率是衡量企业经营表现更核心的指标。</p></blockquote><blockquote><p>随着保费涨幅最终超过了持续攀升的成本，意外伤害险承保商终于从1975年的灾难性业绩中实现了一定程度的反弹。</p></blockquote><blockquote><p>我们保险业务的核心板块——国民赔偿公司的传统汽车险与一般责任险业务，在1976年取得了出色的业绩，盈利水平显著优于行业平均水平。</p></blockquote><blockquote><p>生意划算就做，不划算就拒绝。我们的政策是，不会因为这种自愿业务量波动带来工作量大幅变化裁员。我们宁愿组织时不时有点松弛，也不愿让所有人忙着写我们注定亏钱的生意。</p></blockquote><blockquote><p>克利夫兰的国民城市集团在广告中称，1976年其盈利/平均资产比率约为1.34%，在所有大型银行中位居榜首。但伊利诺伊国民银行的这一指标较其高出近50%，接近2%。</p></blockquote><blockquote><p>我们认为，所投资公司的年度经营进展才是至关重要的。在这一点上，我们对1976年绝大多数投资组合公司的经营表现感到欣喜。</p></blockquote><blockquote><p>我们更愿意看到这样的局面：债券组合的当前市值低于账面价值，但新增资金投资的新债券能提供更具吸引力的利率。</p></blockquote><blockquote><p>我们的政策是集中持仓。我们避免对一家企业或价格兴趣平平的时候买一点点。当我们确信吸引力足够，我们相信值得买入相当数量。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1976年伯克希尔哈撒韦实现历史性反弹。营业利润1607万美元创历史新高，ROE从7.6%强势反弹至17.3%，接近1972年的19.8%历史纪录。保险业务大幅改善：国民赔偿保险综合赔付率从115.4%降至98.7%，远好于行业平均。本土州保险保费增长78%，内布拉斯加玉米壳公司综合成本率创94.4%历史新低。伊利诺伊国民银行ROA接近2%，是大型银行平均的三倍。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1976年-翻译-·-01-letters-1976年-核心总结-·-01-letters-1976年-思维导图" tabindex="-1"><a href="/01_letters/1976年/翻译.html">01_letters/1976年/翻译</a> · <a href="/01_letters/1976年/核心总结.html">01_letters/1976年/核心总结</a> · <a href="/01_letters/1976年/思维导图.html">01_letters/1976年/思维导图</a> <a class="header-anchor" href="#_01-letters-1976年-翻译-·-01-letters-1976年-核心总结-·-01-letters-1976年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1976年/翻译]] · [[→ 核心总结|01_letters/1976年/核心总结]] · [[→ 思维导图|01_letters/1976年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1976年/翻译.html">/01_letters/1976年/翻译</a></li></ul>',22)])])}const q=t(r,[["render",s]]);export{p as __pageData,q as default};
